Definition aop (op : aluop) (A B : av) : option av :=
  match op with
  | ALU_ADD => a_add A B | ALU_SUB => a_sub A B | ALU_AND => a_and A B | ALU_OR => a_or A B
  | ALU_XOR => a_xor A B | ALU_SRL => a_srl A B | ALU_SLL => a_sll A B | ALU_SLTU => a_sltu A B
  | _ => None
  end.
