Lemma mkAlu_add_B : forall bc B imm, bi_nf (mk_binfo bc B) = true -> is_lit B = None ->
  mkAlu ALU_ADD B (ELit imm) = bsum B (addc (mk_binfo bc B) false 0 imm).
Proof.
