Definition probeD (s : expr) (d : dex) (v z : Z) : bool :=
  match evalD s [] d (wrap64 z) with Some w => Z.eqb w v | None => false end.
Lemma probeD_eq : forall s e v z, probeD s (dcomp0 s e) v z = probeS s e v z.
Proof.
