Lemma keys_fold : forall (L : list (expr * Z)) a acc, (forall x, memE x acc = memE x (keys a)) ->
  keys (fold_left (fun a p => bump (fst p) (snd p) a) L a) = keys a ++ nubE_acc (map fst L) acc.
Proof.
