(* [comment removed for export] *)
Definition bigE (e : expr) : bool := negb (esize_le e 48).
Definition rmemo : Type := list (expr * option (Z * Z)).
Definition RMOK (bc : bctx) (m : rmemo) : Prop := forall e r, In (e, r) m -> r = erangeB bc e.
