Lemma mkAlu_add_base : forall bc e imm B k, split_lit e = (B, k) -> is_lit B = None -> bi_nf (mk_binfo bc B) = true ->
  mkAlu ALU_ADD e (ELit imm) = bsum B (addc (mk_binfo bc B) (hask e) k imm).
Proof.
