Definition mk_kix_f (kn : list kentry) : kix :=
  let r := kx_buildF kn xH in KX kn (fst (fst r)) (snd (fst r)) (snd r).
Lemma mk_kix_f_eq : forall l, mk_kix_f l = mk_kix l.
Proof.
